// Cek reservasi yang perlu diingatkan: H-1 dan 2 jam sebelum
const now = new Date();
const nowMs = now.getTime();
const twoHours = 2 * 60 * 60 * 1000;
const oneDay = 24 * 60 * 60 * 1000;

const reminders = [];

$input.all().forEach(item => {
  const r = item.json;
  const dateStr = String(r.date || '').trim();
  const timeStr = String(r.time || '').trim();
  if (!dateStr || !timeStr) return;

  // Parse tanggal - support format: "25 Juni 2025", "25/06/2025", "2025-06-25"
  const months = { januari:0,februari:1,maret:2,april:3,mei:4,juni:5,juli:6,agustus:7,september:8,oktober:9,november:10,desember:11 };
  let reservationDate = null;

  if (dateStr.includes('/')) {
    const [d, m, y] = dateStr.split('/');
    reservationDate = new Date(parseInt(y), parseInt(m) - 1, parseInt(d));
  } else if (dateStr.includes('-')) {
    reservationDate = new Date(dateStr);
  } else {
    // "25 Juni 2025"
    const parts = dateStr.split(' ');
    if (parts.length >= 3) {
      const day = parseInt(parts[0]);
      const month = months[parts[1].toLowerCase()];
      const year = parseInt(parts[2]);
      if (!isNaN(day) && month !== undefined && !isNaN(year)) {
        reservationDate = new Date(year, month, day);
      }
    }
  }

  if (!reservationDate) return;

  // Parse jam - support "19:00", "7 malam", "7pm"
  let hour = 12, minute = 0;
  const timeMatch = timeStr.match(/(\d{1,2})(?::(\d{2}))?/);
  if (timeMatch) {
    hour = parseInt(timeMatch[1]);
    minute = parseInt(timeMatch[2] || '0');
    if (timeStr.toLowerCase().includes('malam') || timeStr.toLowerCase().includes('pm')) {
      if (hour < 12) hour += 12;
    }
  }

  reservationDate.setHours(hour, minute, 0, 0);
  const reservationMs = reservationDate.getTime();
  const diff = reservationMs - nowMs;

  if (diff < 0) return; // sudah lewat

  // Cek H-2 jam
  const needH2 = diff <= twoHours * 1.5 && diff > 0 && String(r.reminder_h2_sent || '').toLowerCase() !== 'true';
  // Cek H-1 (antara 22-26 jam dari sekarang)
  const needH1 = diff >= oneDay - (2 * 60 * 60 * 1000) && diff <= oneDay + (2 * 60 * 60 * 1000) && String(r.reminder_h1_sent || '').toLowerCase() !== 'true';

  if (needH2) {
    reminders.push({
      json: {
        reservation_id: r.reservation_id,
        phone: r.phone,
        customer_name: r.customer_name,
        guests: r.guests,
        date: r.date,
        time: r.time,
        reminder_type: 'h2',
        message: `Halo ${r.customer_name}! ⏰\n\nPengingat: reservasi meja kamu di *Restoran Sasak Lombok* *kurang dari 2 jam lagi!*\n\n📅 ${r.date}\n⏰ ${r.time}\n👥 ${r.guests} orang\n📍 ${$env.RESTAURANT_ADDRESS}\n\nSampai jumpa! 🌶️`
      }
    });
  } else if (needH1) {
    reminders.push({
      json: {
        reservation_id: r.reservation_id,
        phone: r.phone,
        customer_name: r.customer_name,
        guests: r.guests,
        date: r.date,
        time: r.time,
        reminder_type: 'h1',
        message: `Halo ${r.customer_name}! 🍽️\n\nPengingat: besok kamu punya reservasi di *Restoran Sasak Lombok*!\n\n📅 ${r.date}\n⏰ ${r.time}\n👥 ${r.guests} orang\n📍 ${$env.RESTAURANT_ADDRESS}\n\nAda pertanyaan? Hubungi: ${$env.RESTAURANT_PHONE}`
      }
    });
  }
});

return reminders;

const r = $('Cek Reminder Jatuh Tempo').item.json;
const updateData = { reservation_id: r.reservation_id };
if (r.reminder_type === 'h2') updateData.reminder_h2_sent = 'TRUE';
else updateData.reminder_h1_sent = 'TRUE';
return [{ json: updateData }];
